import{_ as e,o as a,c as l,a2 as s}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Invariants","description":"","frontmatter":{"title":"Invariants"},"headers":[],"relativePath":"invariants/index.md","filePath":"invariants/index.md"}'),i={name:"invariants/index.md"};function n(o,t,r,d,c,f){return a(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to &quot;Invariants&quot;">​</a></h1><p>Invariants shape how the solver looks for a viable solution. They are statements that are either assumed to be true or that we want the solver to disprove.</p><h2 id="temporal-logic" tabindex="-1">Temporal Logic <a class="header-anchor" href="#temporal-logic" aria-label="Permalink to &quot;Temporal Logic&quot;">​</a></h2><p>Fault has a couple of temporal logic operators that create SMT rules to test conditions across time. Fault is not as good at temporal logic as other languages specifically designed for it (TLA+ comes to mind), but it can handle some basic reasoning.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Operator</th><th style="text-align:left;">Definition</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>eventually</code></td><td style="text-align:left;">At some point in the model runtime this assertion will be true</td><td style="text-align:left;"><code>assert x eventually;</code></td></tr><tr><td style="text-align:left;"><code>always</code></td><td style="text-align:left;">This assertion is always true (technically the default for all assertions)</td><td style="text-align:left;"><code>assert x always;</code></td></tr><tr><td style="text-align:left;"><code>eventually-always</code></td><td style="text-align:left;">When this assertion becomes true it will stay true for the rest of the model runtime</td><td style="text-align:left;"><code>assert x eventually-always;</code></td></tr><tr><td style="text-align:left;"><code>nmt n</code></td><td style="text-align:left;">This assertion is true no more than n times</td><td style="text-align:left;"><code>assert x nmt 2;</code></td></tr><tr><td style="text-align:left;"><code>nft n</code></td><td style="text-align:left;">This assertion is true no fewer than n times</td><td style="text-align:left;"><code>assert x nft 2;</code></td></tr><tr><td style="text-align:left;"><code>available</code></td><td style="text-align:left;">An <code>unfunc</code>&#39;s precondition is satisfiable from the initial state</td><td style="text-align:left;"><code>assume f available;</code></td></tr></tbody></table>',5)])])}const x=e(i,[["render",n]]);export{m as __pageData,x as default};
